correct_example.code:
function _removeTokenEnumeration(address from, address to, uint256 id, uint256 amount) internal {
    if (to == address(0)) {
        _idTotalSupply[id] -= amount;
        // FIX: check post-burn supply
        if (_idTotalSupply[id] == 0) _removeTokenFromAllTokensEnumeration(id);
    }
}

function reclaimRentalOrder(RentalOrder calldata rentalOrder) external {
    for (uint256 i = 0; i < rentalOrder.items.length; ++i) {
        Item memory item = rentalOrder.items[i];
        if (item.itemType == ItemType.ERC1155) {
            // FIX: update state first (CEI)
            rentedAssets[item.rentalId] = 0;
            delete rentalOrder.items[i];
            _transferERC1155(item, rentalOrder.lender);
        }
    }
}
